	runtime.LockOSThread()
	defer runtime.UnlockOSThread()

	// 2. Создаем слушающий сокет
	listenFd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_STREAM, 0)
	if err != nil {
		log.Fatalf("Ошибка создания сокета: %v", err)
	}
	defer syscall.Close(listenFd)

	_ = syscall.SetsockoptInt(listenFd, syscall.SOL_SOCKET, syscall.SO_REUSEADDR, 1)
	_ = syscall.SetNonblock(listenFd, true)

	sa := &syscall.SockaddrInet4{Port: 9092}
	copy(sa.Addr[:], net.ParseIP("127.0.0.1").To4())
	if err := syscall.Bind(listenFd, sa); err != nil {
		log.Fatalf("Ошибка bind: %v", err)
	}

	if err := syscall.Listen(listenFd, 64); err != nil {
		log.Fatalf("Ошибка listen: %v", err)
	}

	// 3. Создаем epoll
	epfd, err := syscall.EpollCreate1(0)
	if err != nil {
		log.Fatalf("Ошибка epoll: %v", err)
	}
	defer syscall.Close(epfd)

	ev := syscall.EpollEvent{
		Events: syscall.EPOLLIN,
		Fd:     int32(listenFd),
	}
	_ = syscall.EpollCtl(epfd, syscall.EPOLL_CTL_ADD, listenFd, &ev)

	fmt.Println("Однопоточный Event-Driven сервер запущен на 127.0.0.1:9092 (0 горутин)")

	// Запускаем фоновый тестовый клиент
	go func() {
		time.Sleep(100 * time.Millisecond)
		conn, err := net.Dial("tcp", "127.0.0.1:9092")
		if err == nil {
			defer conn.Close()
			_, _ = conn.Write([]byte("PING\n"))
			res := make([]byte, 32)
			n, _ := conn.Read(res)
			fmt.Printf("[Тестовый клиент] Ответ от однопоточного сервера: %s", string(res[:n]))
		}
	}()

	events := make([]syscall.EpollEvent, 16)
	buf := make([]byte, 1024)

	// 4. Однопоточный Event Loop (Redis / Node.js модель)
	iterations := 0
	for iterations < 3 {
		iterations++
		n, err := syscall.EpollWait(epfd, events, 300)
		if err != nil {
			if err == syscall.EINTR {
				continue
			}
			break
		}

		for i := 0; i < n; i++ {
			fd := int(events[i].Fd)

			if fd == listenFd {
				// Прием нового клиента
				clientFd, _, err := syscall.Accept(listenFd)
				if err == nil {
					_ = syscall.SetNonblock(clientFd, true)
					clientEv := syscall.EpollEvent{
						Events: syscall.EPOLLIN,
						Fd:     int32(clientFd),
					}
					_ = syscall.EpollCtl(epfd, syscall.EPOLL_CTL_ADD, clientFd, &clientEv)
					fmt.Printf("[Event Loop] Принято соединение clientFd=%d\n", clientFd)
				}
			} else {
				// Обработка данных клиента прямо в текущем потоке
				nRead, err := syscall.Read(fd, buf)
				if err != nil || nRead == 0 {
					syscall.Close(fd)
					continue
				}

				if string(buf[:4]) == "PING" {
					_, _ = syscall.Write(fd, []byte("PONG\n"))
				} else {
					_, _ = syscall.Write(fd, buf[:nRead])
				}
				syscall.Close(fd)
			}
		}
	}
	fmt.Println("Однопоточный цикл событий успешно завершил демонстрационную фазу.")
}

package main

import (
	"errors"
	"fmt"
	"log"
	"os"
	"syscall"
)

func main() {
	// 1. Создаем временный файл
	f, err := os.CreateTemp("", "sec_file_*.txt")
	if err != nil {
		log.Fatalf("Ошибка создания файла: %v", err)
	}
	path := f.Name()
	_ = f.Close()
	defer os.Remove(path)

	// 2. Устанавливаем права 0644 (rw-r--r--)
	const targetMode uint32 = 0644
	if err := syscall.Chmod(path, targetMode); err != nil {
		log.Fatalf("Ошибка syscall.Chmod: %v", err)
	}
	fmt.Printf("Права доступа к файлу успешно изменены на %04o\n", targetMode)

	// 3. Проверяем установленные права через stat
	var stat syscall.Stat_t
	if err := syscall.Stat(path, &stat); err != nil {
		log.Fatalf("Ошибка stat: %v", err)
	}

	actualMode := stat.Mode & 0777
	fmt.Printf("Фактические права файла в inode: %04o\n", actualMode)
	fmt.Printf("Владелец файла: UID=%d, GID=%d\n", stat.Uid, stat.Gid)

	// 4. Попытка смены владельца файла (chown)
	// Для непривилегированного пользователя это должно вернуть EPERM
	err = syscall.Chown(path, 0, 0) // попытка передать файл пользователю root (UID=0)
	if err != nil {
		if errors.Is(err, syscall.EPERM) {
			fmt.Println("Ожидаемая ошибка EPERM: смена владельца файла требует прав суперпользователя (CAP_CHOWN).")
		} else {
			fmt.Printf("Ошибка syscall.Chown: %v\n", err)
		}
	} else {
		fmt.Println("Владелец файла успешно изменен на root (программа запущена с правами суперпользователя).")
	}
}

package main

import (
	"encoding/binary"
	"fmt"
	"log"
	"syscall"
	"time"
	"unsafe"
)

// Структуры времени для timerfd_settime
type itimerspec struct {
	it_interval syscall.Timespec // Интервал периодического таймера
	it_value    syscall.Timespec // Начальное время первого срабатывания
}

func main() {
	const (
		SYS_TIMERFD_CREATE  = 283
		SYS_TIMERFD_SETTIME = 286
		CLOCK_MONOTONIC     = 1
		TFD_NONBLOCK        = 0x800
		TFD_CLOEXEC         = 0x80000
	)

	// 1. Создаем timerfd
	tfd, _, errno := syscall.Syscall(
		SYS_TIMERFD_CREATE,
		uintptr(CLOCK_MONOTONIC),
		uintptr(TFD_NONBLOCK|TFD_CLOEXEC),
		0,
	)
	if errno != 0 {
		log.Fatalf("Ошибка timerfd_create: %v", errno)
	}
	defer syscall.Close(int(tfd))
	fmt.Printf("Timerfd успешно создан с флагом TFD_NONBLOCK (fd=%d)\n", tfd)

	// 2. Настраиваем таймер: первый запуск через 50 мс, затем каждые 100 мс
	newVal := itimerspec{
		it_interval: syscall.Timespec{Sec: 0, Nsec: 100 * 1000 * 1000}, // 100 мс
		it_value:    syscall.Timespec{Sec: 0, Nsec: 50 * 1000 * 1000},  // 50 мс
	}

	_, _, errno = syscall.Syscall6(
		SYS_TIMERFD_SETTIME,
		tfd,
		0, // относительное время
		uintptr(unsafe.Pointer(&newVal)),
		0, 0, 0,
	)
	if errno != 0 {
		log.Fatalf("Ошибка timerfd_settime: %v", errno)
	}
	fmt.Println("Таймер взведен на периодический тик каждые 100 мс.")

	// 3. Создаем epoll и добавляем timerfd
	epfd, err := syscall.EpollCreate1(0)
	if err != nil {
		log.Fatalf("Ошибка epoll: %v", err)
	}
	defer syscall.Close(epfd)

	ev := syscall.EpollEvent{
		Events: syscall.EPOLLIN,
		Fd:     int32(tfd),
	}
	if err := syscall.EpollCtl(epfd, syscall.EPOLL_CTL_ADD, int(tfd), &ev); err != nil {
		log.Fatalf("Ошибка EpollCtl: %v", err)
	}

	// 4. Ожидаем срабатывания таймера в цикле событий
	events := make([]syscall.EpollEvent, 1)
	buf := make([]byte, 8) // timerfd возвращает 8-байтовое число пропущенных тиков

	fmt.Println("Запуск ожидания тиков таймера в epoll_wait...")
	start := time.Now()

	for tickCount := 1; tickCount <= 3; tickCount++ {
		n, err := syscall.EpollWait(epfd, events, 2000)
		if err != nil {
			log.Fatalf("Ошибка epoll_wait: %v", err)
		}

		if n > 0 && events[0].Fd == int32(tfd) {
			nRead, err := syscall.Read(int(tfd), buf)
			if err != nil {
				log.Fatalf("Ошибка чтения timerfd: %v", err)
			}
			if nRead == 8 {
				expirations := binary.LittleEndian.Uint64(buf)
				elapsed := time.Since(start)
				fmt.Printf("[Тик %d] Срабатываний таймера ядра: %d | Прошло: %v\n", tickCount, expirations, elapsed)
			}
		}
	}
	fmt.Println("Прецизионный цикл таймера timerfd успешно завершен.")
}
